-- ============================================================
-- Migration 005 — Kategori ağacı yeniden yapılandırma (11 ana dal)
--   Elektrik · Elektronik · Elektromekanik · Mekanik · Ev Elektroniği
--   · 3D Baskı · Alet & Ekipman · Sarf Malzeme · Çeyiz & Züccaciye
--   · Sağlık · Diğer
-- Uygulama: phpMyAdmin > İçe Aktar, veya: mysql < 005_category_tree.sql
--
-- GÜVENLİ/İDEMPOTENT: Aynı kodu taşıyan mevcut kategoriler AYNI UUID ile
-- güncellenir (parçaların kategori bağları KORUNUR); ağaçta olmayan eskiler
-- soft-delete edilir; yeni dallar eklenir. İki kez çalıştırmak zarar vermez.
-- SONRA: her cihazda uygulamada ÇIKIŞ → tekrar GİRİŞ (yeni ağaç böylece iner).
-- ============================================================

SET NAMES utf8mb4;
SET @tenant := (SELECT id FROM tenants ORDER BY created_at ASC LIMIT 1);
SET @now := CURRENT_TIMESTAMP(3);

-- 1) Mevcut tüm kategorileri soft-delete (yeni ağaçta olanlar 2. adımda dirilir)
UPDATE categories SET deleted_at = @now, updated_at = @now
 WHERE tenant_id = @tenant AND deleted_at IS NULL;

-- 2) Yeni ağacı upsert (id VEYA (tenant,code) çakışırsa: güncelle + dirilt)
ON DUPLICATE KEY UPDATE
  parent_id = VALUES(parent_id), name_tr = VALUES(name_tr), name_en = VALUES(name_en),
  sku_template = VALUES(sku_template), default_count_mode = VALUES(default_count_mode),
  attribute_schema = VALUES(attribute_schema), sort_order = VALUES(sort_order),
  updated_at = VALUES(updated_at), deleted_at = NULL;

-- 3) Silinmiş (ağaçta artık olmayan) kategoriye işaret eden parçaları serbest bırak
UPDATE parts p JOIN categories c ON c.id = p.category_id
   SET p.category_id = NULL, p.updated_at = @now
 WHERE p.tenant_id = @tenant AND c.deleted_at IS NOT NULL;
